<template><section class="ops-panel"><div class="ops-toolbar"><div><h2>平台服务价格</h2><p class="ops-muted">价格按不可变版本发布，只用于平台服务额度扣减，不代表供应商实际消费。</p></div><el-button v-if="canWrite" type="primary" size="small" @click="dialog=true">发布价格版本</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-table :data="rows" v-loading="loading"><el-table-column prop="modelId" label="模型 ID" min-width="160" /><el-table-column prop="version" label="价格版本" min-width="130" /><el-table-column label="每计量单位扣减（元）" min-width="240"><template slot-scope="s"><div v-for="(value,key) in s.row.metricRates" :key="key">{{ key }} · {{ value }}</div></template></el-table-column><el-table-column label="单次调用用量上限" min-width="220"><template slot-scope="s"><div v-for="(value,key) in s.row.maxUsage" :key="key">{{ key }} · {{ value }}</div></template></el-table-column></el-table><el-dialog title="发布平台服务价格" :visible.sync="dialog" width="min(570px,92vw)" :close-on-click-modal="false"><el-form label-width="100px"><el-form-item label="模型 ID"><el-input v-model="form.modelId" /></el-form-item><el-form-item label="新版本"><el-input v-model="form.version" /></el-form-item><el-form-item label="单位价格"><el-input v-model="form.metricRates" type="textarea" :rows="4" placeholder='{"input_tokens":"0.000002","output_tokens":"0.000008"}' /><p class="ops-muted">每个 Token、秒或字符对应的元额度；必须与服务真实计量单位一致。</p></el-form-item><el-form-item label="调用上限"><el-input v-model="form.maxUsage" type="textarea" :rows="4" placeholder='{"input_tokens":"4096","output_tokens":"1024"}' /></el-form-item></el-form><el-alert v-if="saveError" :title="saveError" type="error" :closable="false" /><span slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">发布新版本</el-button></span></el-dialog></section></template>
<script>
import { operations } from '@/apis/platform';
import { hasPermission } from '@/security/session';
export default {
  data() { return { rows: [], loading: false, error: '', dialog: false, form: { modelId: '', version: '', metricRates: '', maxUsage: '' }, saving: false, saveError: '' }; },
  computed: { canWrite() { return hasPermission(this.$store.state.userInfo, 'rates.write'); } }, created() { this.load(); },
  methods: {
    async load() { this.loading = true; this.error = ''; try { this.rows = ((await operations.rates()).list || []).map(row => ({ ...row, metricRates: row.metricRates || JSON.parse(row.metricRatesJson || '{}'), maxUsage: row.maxUsage || JSON.parse(row.maxUsageJson || '{}') })); } catch (error) { this.error = error.message; } finally { this.loading = false; } },
    async save() { if (this.saving || !this.canWrite) return; this.saveError = ''; let metricRates, maxUsage; try { metricRates = JSON.parse(this.form.metricRates); maxUsage = JSON.parse(this.form.maxUsage); for (const value of [metricRates,maxUsage]) if (!value || Array.isArray(value) || typeof value !== 'object' || !Object.keys(value).length || Object.values(value).some(amount => !/^\d+(\.\d+)?$/.test(String(amount)))) throw new Error(); } catch (_) { this.saveError = '价格和调用上限需填写非负数值的 JSON 对象'; return; } if (!this.form.modelId.trim() || !this.form.version.trim()) { this.saveError = '请填写模型 ID 和新版本'; return; } this.saving = true; try { await operations.addRate({ modelId: this.form.modelId.trim(), version: this.form.version.trim(), metricRates, maxUsage }); this.dialog = false; this.form = { modelId: '', version: '', metricRates: '', maxUsage: '' }; await this.load(); } catch (error) { this.saveError = error.message; } finally { this.saving = false; } },
  },
};
</script>
